#include "runtime.h"
namespace ShenPulse { namespace Hiking {
void Menu(){static bool open=false,wasF10=false;static int row=0;static ULONGLONG nextKey=0;static std::string notice;const auto now=GetTickCount64();bool f10=(GetAsyncKeyState(VK_F10)&0x8001)!=0;if(f10&&!wasF10)open=!open;wasF10=f10;if(!open)return;CONTROLS::DISABLE_ALL_CONTROL_ACTIONS(0);CONTROLS::DISABLE_ALL_CONTROL_ACTIONS(1);
 std::vector<std::string> rows={"Nouvelle randonnee",std::string("Vehicules : ")+(allowDriving?"AUTORISES":"NON"),std::string("Compteur de points : ")+(showCounter?"OUI":"NON"),"Point suivant","Point precedent","Retour au depart","Nouveau parcours depuis ici","Ajouter un point ici","Terminer le parcours ici","Modifier le depart ici","Parcours par defaut","Fermer"};
 if(now>=nextKey){bool up=GetAsyncKeyState(VK_UP)&0x8001,down=GetAsyncKeyState(VK_DOWN)&0x8001,enter=GetAsyncKeyState(VK_RETURN)&0x8001,back=GetAsyncKeyState(VK_BACK)&0x8001;if(up||down||enter||back)nextKey=now+220;if(up)row=(row+static_cast<int>(rows.size())-1)%rows.size();if(down)row=(row+1)%rows.size();if(back)open=false;if(enter){Request r;Ped ped=PLAYER::PLAYER_PED_ID();if(row==0){if(route.size()<2)notice="Ajoutez au moins deux points";else Start(now);}else if(row==1){allowDriving=!allowDriving;SaveRoute();}else if(row==2){showCounter=!showCounter;SaveRoute();}else if(row>=3&&row<=5){r.code=row==3?"hike_forward":row==4?"hike_back":"hike_start";notice=Execute(r).message;}else if(row==6){startPoint=Position(ped);route.clear();progress.running=false;progress.outcome=0;restartAt=0;active=true;notice="Ajoutez les points puis l'arrivee";}else if(row==7){if(route.size()<99){route.push_back(Position(ped));notice=std::to_string(route.size())+" points prepares";}}else if(row==8){if(route.size()<100)route.push_back(Position(ped));if(route.size()<2)notice="Ajoutez au moins deux points";else{SaveRoute();Start(now);notice="Parcours sauvegarde";}}else if(row==9){startPoint=Position(ped);SaveRoute();notice="Depart sauvegarde";}else if(row==10){DefaultRoute();SaveRoute();Start(now);notice="Parcours par defaut restaure";}else open=false;}}
 if(!open)return;GRAPHICS::DRAW_RECT(.2f,.4f,.36f,.68f,7,12,25,230);DrawText("SHENPULSE HIKING",.2f,.075f,.55f,60,235,210);for(size_t i=0;i<rows.size();i++){if(i==row)GRAPHICS::DRAW_RECT(.2f,.15f+i*.04f,.35f,.038f,40,130,110,220);DrawText(rows[i],.2f,.135f+i*.04f,.32f);}DrawText("Duree : "+std::to_string(durationSeconds/60)+" min (page ShenPulse)",.2f,.65f,.28f,150,210,240);DrawText(notice,.2f,.69f,.26f,255,200,100);
}
} }
